draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // Draw clock for 8
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 100 + 40 * Math.sin(t), H/2 + 40 * Math.cos(t));
  ctx.stroke();

  // Draw snake for 2
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 + 50 * Math.sin(2*t), H/2 - 50 + 50 * Math.cos(2*t));
  ctx.stroke();

  // Draw wave for 8
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 - 50);
  ctx.lineTo(W/2 + 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2);
  ctx.lineTo(W/2 + 150 + 20 * Math.sin(3*t), H/2 + 20 * Math.cos(3*t));
  ctx.stroke();

  ctx.restore();
}
